INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Acno''s Energizer', 'Acno''s Energizer is a flash game developed by Uselab and published on the Miniclip flash portal in 2000. Acno''s Energizer is a puzzle game where the player maneuvers Acno, a little yellow sprite, around a room with goal of getting one or more red orbs into the portal to "energize" it and move to the next level.' FROM games WHERE igdb_id = 326749 ON CONFLICT (game_id, language_code) DO NOTHING;
