INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sudden Strike 2', 'Sudden Strike II is a WWII themed R.T.S that lets the player choose between the British, American, Japanese and German campaigns, sometimes consisting of clearing the area of enemies or killing a general. Sudden Strike II allows you to take control of land, sea and air making for spectacular battles.' FROM games WHERE igdb_id = 22063 ON CONFLICT (game_id, language_code) DO NOTHING;
