INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deer Hunter 2003: Legendary Hunting', 'In Deer Hunter 2003, players hunt on huge maps covering more than five square miles in swamps, farmland, northern forests and mountains in world-class hunting locations such as Alabama, Iowa, Quebec, Wyoming and British Columbia. Players will have a large variety of sporting arms to choose from that include guns, bows, and handguns. Providing the ultimate hunting experience, Deer Hunter 2003 allows players to use such equipment as grunt calls, scents, binoculars, and tree stands.' FROM games WHERE igdb_id = 261 ON CONFLICT (game_id, language_code) DO NOTHING;
