INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Fandom Vol. 1: Cress Version', 'Tales of Fandom Vol. 1 is a compilation game for the Sony PlayStation. It includes gameplay that features characters and elements from Tales of Phantasia, Tales of Destiny, and Tales of Eternia. The game is set up as an adventure game with actual gameplay elements to explore and unlock extra bits. Some elements in the game include exploring, playing a puzzle game like the Craymel Lab, a scene maker where characters can play out a created scenario, and an extensive gallery. It was released on January 31, 2002 and only sold in Japan.' FROM games WHERE igdb_id = 100158 ON CONFLICT (game_id, language_code) DO NOTHING;
