INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Deeper Kyo', 'Unlock the mystery behind the sudden reappearance of the legendary swordsmen Demon Eyes Kyo in this fast-paced action adventure. Take up your weapons and battle against hordes of enemies, as you experience the story of Samurai Deeper Kyo! Features: Perform devastating special moves. Play as Demon Eyes Kyo, Kyoshiro Mibu, Yuya Shiina, Yukimura Sanada, or Benitora. Unlock powerful weapons and extra modes.' FROM games WHERE igdb_id = 49424 ON CONFLICT (game_id, language_code) DO NOTHING;
