INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gyakuten Saiban 2', 'Gyakuten Saiban 2 (original version of Phoenix Wright: Ace Attorney - Justice for All) is a visual novel adventure video game. It was originally released for the Game Boy Advance in 2002 in Japan. The game is the second entry in the Ace Attorney series, following Gyakuten Saiban (Phoenix Wright: Ace Attorney).' FROM games WHERE igdb_id = 221289 ON CONFLICT (game_id, language_code) DO NOTHING;
