INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wind-fantasy-ii-alive', 350516, '2002-09-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa0qk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3rp1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wind Fantasy II: Alive', 'Shuilan is a land that hovers above the ocean. Recently, a demon lord appeared nearby. The people of Shuilan know that the demon lord''s plan is to invade and to conquer their country. The wise teacher Wentini builds a special unit of fighters, called the Fate Travel Group. She knows that the only one who can help the people of Shuilan is a girl with special powers, named Li Fu. She sends a young fighter named Ares to find Li Fu, but meanwhile Shuilan is invaded by a hostile army. The battles for survival begins... Fengse Huanxiang 2, also known as Wind Fantasy II, is set in a fantasy world, unlike most Chinese RPGs, which prefer concrete historical setting in China. The game is more close to Japanese RPGs in style, being heavily influenced by anime art. Unlike other games in the series, it has no elements of strategy/tactical RPG. You navigate your party from location to location, fighting random enemies and bosses on the way. The game uses Final Fantasy-like third-person perspective in battles, yet the battle engine is not active time, but turn-based.' FROM games WHERE igdb_id = 350516 ON CONFLICT (game_id, language_code) DO NOTHING;
