INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Jedi Knight II: Jedi Outcast Demo', 'The Jedi Knight II: Jedi Outcast demo was released in 2002, offering players a preview of Raven Software’s sequel to Jedi Knight. It features an exclusive single-player mission set on the Imperial outpost of Kejim, where Kyle Katarn and Jan Ors investigate mysterious Remnant activities. It showcases the game’s blend of first-person shooting and third-person lightsaber combat, along with Force powers that became central to the full game.' FROM games WHERE igdb_id = 367367 ON CONFLICT (game_id, language_code) DO NOTHING;
