INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elevator Action: Old & New', 'A Japanese exclusive update to Elevator Action. Elevator Action Old & New is an action game developed by Taito and published by MediaKite for Game Boy Advance. Elevator Action Old & New contains the original version of Elevator Action as well as a re-worked arranged version. The new version of the game features completely re-drawn graphics, multiple playable characters with unique abilities, new enemies, items, and more.' FROM games WHERE igdb_id = 49284 ON CONFLICT (game_id, language_code) DO NOTHING;
