INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winter X-Games Snowboarding 2002', 'The most authentic snowboarding game returns! Winter X Games Snowboarding 2002 features more arcade fun and snowboarding action. Win a gold medal in on of four authentic Winter X Games events, or go anywhere in the free ride mode, where you can pull off big kickers and twisted rails to your heart''s content.' FROM games WHERE igdb_id = 47303 ON CONFLICT (game_id, language_code) DO NOTHING;
