INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kamaitachi no Yoru 2: Kangokujima no Warabe Uta', 'Kamai Tachi no Yoru 2: Jail Island no Warabe Uta is a video game published by Chunsoft and released on July 18, 2002 as an adventure game for the PlayStation 2. It is Chunsoft''s fourth sound novel. The previous game, "Night of the Kamai Tachi", is used as a Story within a story. The sequel is "Kamaitachi no Yoru x3: Crescent Moon Island Case no Shinsou".' FROM games WHERE igdb_id = 64840 ON CONFLICT (game_id, language_code) DO NOTHING;
