INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The PowerPuff Girls: Relish Rampage', 'Mojo Jojo is fed up with The Powerpuff Girls. He''s invented a scheme to put all of Townsville under his mind control...Radio Jojo! But Mojo doesn''t know his sour signals are strong enough to summon aliens to invade Townsville! As The Powerpuff Girls, you must defeat Mojo and annihilate the aliens before the Townsville citizens become aliens forever! Battle your way through level upon level of interesting missions and outrageous clashes in a 3-D Townsville world. The survival of everyone''s favorite superheroes, The Powerpuff Girls, depends on you!' FROM games WHERE igdb_id = 19415 ON CONFLICT (game_id, language_code) DO NOTHING;
