INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pocket-monsters-suuji-wo-tsukamaeyou', 63849, '2002-07-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co805u.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Monsters: Suuji wo Tsukamaeyou!', 'Pokémon: Catch the Numbers! is an educational game for Sega Pico. It has only been released in Japan. Team Rocket has stolen all of Ash, Misty, and Brock''s Pokémon except for Pikachu and Togepi. The player needs to complete a series of mini-games, mostly math related, to get them back. The game features voice acting from the anime''s cast and an instrumental version of Aim to Be a Pokémon Master as the title theme. The very first Nintendo-produced game to be released for a Sega console.' FROM games WHERE igdb_id = 63849 ON CONFLICT (game_id, language_code) DO NOTHING;
