INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kengo 2: Sword of the Samurai', 'The second game in the Kengo series was released for the PlayStation 2 in Japan on June 27, 2002. It was released in Europe on February 14, 2003 under the title Sword of the Samurai. It features a character creation feature and over 100 detailed swords to choose from. Published by Ubisoft. Ubisoft announced a US release to be called Kengo: Legacy of the Blade at one point but the deal ended up falling through, thus it was never released.' FROM games WHERE igdb_id = 1421 ON CONFLICT (game_id, language_code) DO NOTHING;
