INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monsters, Inc.: Wreck Room Arcade - Bowling for Screams', 'This game is part of the Wreck Room Arcade series which consists of four different "activities". You can buy and play them separately, but they link into the same main menu - and, if you have bought them all, you get another bonus game for free (it will be unlocked after you''ve installed the last game). "Bowling for Screams" is a fun bowling game with the characters from the Disney/Pixar movie "Monsters Inc.". It''s no normal bowling - the lanes are littered with obstacles and you can maneuver the bowling ball with the arrow keys.' FROM games WHERE igdb_id = 69595 ON CONFLICT (game_id, language_code) DO NOTHING;
