INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Hello Kitty Series Vol. 2: Minna de Sugoroku', 'Minna de Sugoroku is the second sugoroku game based on Hello Kitty characters, the first one was Gotouchi Hello Kitty Sugoroku Monogatari in the Playstation One console. The gameplay is the classic board game with mini puzzle and action diversions, each character has some star movements and when the stars reach 0 the character has to rest, in each board the player has to reach the board''s goal first to win the match.' FROM games WHERE igdb_id = 203350 ON CONFLICT (game_id, language_code) DO NOTHING;
