INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-bust-a-move-2', 43576, '2002-09-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1p22.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scnlxk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Bust-A-Move 2', 'Super Bust-A-Move 2 offers arcade-style action and screen-clearing puzzle solving in an immersive environment full of vivid characters. It features a single-player puzzle mode that lets you play through multiple stages and multiple game types as each of the stories behind each of the game''s characters is explained, and information is gradually revealed. There is also a battle mode that lets you challenge your friends or the computer as you compete in a best-of-three match. You can also create your own mind-bending, bubble-busting puzzles, play them, and save them to a memory card to challenge your friends. There is a scalable difficulty feature that adjusts the game for players of all skill levels.' FROM games WHERE igdb_id = 43576 ON CONFLICT (game_id, language_code) DO NOTHING;
