INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medabots: Rokusho', 'Join Ikki as he begins his journey as a Medafighter and tries to save his hometown of Riverview City from the evil Rubberobo Gang. Interact with characters and control Medabots popular in the Medabots TV animated series. Create your own special Medabot from hundreds of unique Medaparts! Robattle and trade Medaparts with friends. Each version of Medabots offers exclusive Medaparts and Medals not found in the other.' FROM games WHERE igdb_id = 49235 ON CONFLICT (game_id, language_code) DO NOTHING;
