INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('slam-tennis', 47338, '2002-08-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/bxlfckn6zddvh5umzqil.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vl7lbyiffhkxjcxnxjez.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slam Tennis', 'Slam Tennis goes where no tennis game has gone before - this is liquid tennis with attitude. A game that recreates then amplifies the excitement, atmosphere and challenge of modern professional tennis. In Slam Tennis overcoming your opponent is only part of the challenge. Two different extremes of tennis are combined here. The four Grand Slam venues are among the 11 featured, but so are a mansion and a dance hall. These surfaces all affect ball speed and bounce. A few real players such as Carlos Moya and Tim Henman are included, but most are created for the game - a lifeguard and a mayor are included, with abilities based on their real-life work. As well as playing individual Exhibition matches, you can take on an Arcade challenge of defeating the 16 players or take on the full Slam Tennis Championship event. Forehand, backhand and lob shots are all available. There are also sub-games: Crazy Collapsing Columns, Bubble Bursting Bonanza, Rocking Ring Riot, and Sand, Sea and Serve,' FROM games WHERE igdb_id = 47338 ON CONFLICT (game_id, language_code) DO NOTHING;
