INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NHL FaceOff 2003', 'NHL FaceOff 2003 is an ice hockey video game made by SolWorks and published by Sony Computer Entertainment of America, released on the PlayStation 2. It features then-Colorado Avalanche defenceman Rob Blake on its cover. Mike Emrick and Darren Pang return from the game''s predecessor, NHL FaceOff 2001, to provide commentary.' FROM games WHERE igdb_id = 20434 ON CONFLICT (game_id, language_code) DO NOTHING;
