INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Mystery of the Nautilus', 'This adventure game was inspired by the Jules Verne novel "20,000 Leagues Under the Sea". The story begins aboard the USS Shark, a research submarine, exploring the depths of the Atlantic Ocean. The crew discovers a huge metallic object and argues whether to further examine it. During the debate, a young scientist, taking it upon himself to go without orders, steals a mini-sub and docks at the mysterious wreck. You play the scientist aboard what he learns to be Captain Nemo''s vessel the "Nautilus". There are many rooms to explore and numerous puzzles to be solved in this 1st person point-and-click adventure game.' FROM games WHERE igdb_id = 73345 ON CONFLICT (game_id, language_code) DO NOTHING;
