INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('makai-toushi-saga', 84142, '2002-03-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ba8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7m5f.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Makai Toushi SaGa', 'Makai Toushi SaGa or The Final Fantasy Legend, is the first entry in the SaGa series, released in 1989 on the Game Boy. The WonderSwan Color remake featured several changes from the original. The graphics were updated to 16-bit level with new sprites and artwork drawn by Toshiyuki Itahana. New animated sequences were added to the game as well like the intro sequence. Other new features included a bestiary and the ability to re-target enemies when a previous target is slain by another character.' FROM games WHERE igdb_id = 84142 ON CONFLICT (game_id, language_code) DO NOTHING;
