INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inquisition', 'Inquisition is a third-person 3D real time action/adventure game. It offers a blend of action, infiltration and adventure in a medieval universe. Sneaking between homes and past sleeping guards, players will need to keep themselves from being spotted, hopping from ledge to ledge and from roof to roof, picking locks, striking the enemy, gleaning and stealing information without the enemy knowing : these are the kind of actions that will bring players closer to discovering the hiding place of the Templar knights’ treasure. Players are also given different means of exploring and moving around in total secrecy: creeping silently and hiding in shadows. There are riddles closely linked to the scenario which they will need to solve over the course of their adventure: finding and opening passageways, gathering objects and using them wisely.' FROM games WHERE igdb_id = 69840 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 69840 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
