INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Maze of the Kings', 'A 1 to 2 player shooting game where each player assumes the role of an archaeological treasure hunter armed with a magical cane who travels across rivers and deserts and explores the insides of pyramids searching for lost treasure while killing mummies and other evil creatures. Each player gets a choice of what kind of firepwoer to use for his or her character''s magical cane: Light, Spark, or Fire.' FROM games WHERE igdb_id = 39793 ON CONFLICT (game_id, language_code) DO NOTHING;
