INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kinnikuman-nisei-dream-tag-match', 37365, '2002-04-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/dmnbim9qblfdjxffbtyq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm7oe.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kinnikuman Nisei: Dream Tag Match', 'Kinnikuman Nisei: Dream Tag Match is a wrestling game based in the manga/anime series of the same name. It features the cast of Kinnikuman Nisei (known in the West as "Kinnikuman: Second Generations") in a battle to victory. The main story follows Kid Muscle, the prince of Muscle Planet and son of King Muscle (the early protagonist of the series), who fought for peace and justice in the Universe. Kid has now been chosen as King Muscle''s predecessor in wrestling history, and must now defeat every opponent that comes his way, stopping total domination by the Demon Manufacturing Plant, an evil wrestling league which wants to take control of the universe, and the loss of his fanbase, which includes the love of his life, Roxanne. This game supports up to 2 players and includes 14 characters (which aren''t all available from the beginning). Game modes are Story Mode (in which you will fight as Kid Muscle, and will have to defeat all your opponents), Tag Mode (you will have to choose a companion and confront other 10 couples, if you win, you will unlock a character), Classic Mode (this one will be available once you unlock all the characters of the game, and once done, it will let you play a port of the original Kinnikuman NES game).' FROM games WHERE igdb_id = 37365 ON CONFLICT (game_id, language_code) DO NOTHING;
