INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Creator: Harry Potter and the Chamber of Secrets', 'LEGO Creator: Harry Potter and the Chamber of Secrets is an adventure/puzzle game where players can explore the a range of environments from Harry''s second year, including Hogwarts, the Quidditch pitch, the Dark Forest, Diagon Alley, and even the mysterious Chamber of Secrets itself. On this journey, players will collect chocolate frogs, find LEGO treasure chests, and cast spells at characters, creatures, and models. In addition, players can fully customize their adventure by building structures and characters in the workshop and dropping their creations into the world of Hogwarts.' FROM games WHERE igdb_id = 78288 ON CONFLICT (game_id, language_code) DO NOTHING;
