INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('galidor-quest', 214944, '2002-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co559q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scijx5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galidor Quest', 'The Outer Dimension is under attack from the tyrannical warlord Gorm, who will stop at nothing until everything is either under his rule or destroyed. As a native of this dimension, you have the power to instantly swap arms and legs with those of any other being; an ability referred to as "glinching". Could finding the strongest limbs be the key to stopping Gorm? Galidor Quest is an online role-playing game based on LEGO''s Galidor franchise. Players can choose from a selection of five species when creating their character, with the ability to start with the arms and legs of any of those species. The player character''s statistics are improved by solving puzzles, completing tasks assigned by NPCs (which are usually in the form of mini-games that take place in the same level), and defeating other characters in challenges. "Challenges" are duels where the player must guess whether a given statistic is better than their opponent''s. If the player guesses correctly, they can choose to glinch their limbs with those of their opponent, which can be useful if the opponent has limbs with better stats; however, if the player guesses incorrectly, the opponent can choose to take the player''s higher-levelled limbs instead. There is an inventory system for storing quest items and a total of four worlds to explore.' FROM games WHERE igdb_id = 214944 ON CONFLICT (game_id, language_code) DO NOTHING;
