INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Studios Backlot', 'You''ve arrived at LEGO Studios for an afternoon tour, but thins change when action star Johnny Thunder asks desperately for help with retrieving his lost hat, gun, and binoculars. Help him and you''ll get hired on the spot, now working at the backlot as multiple film crews struggle to complete a day''s work. This early 3D Shockwave game features a blend of simple adventure puzzling and Havok physics-based platforming. Learn the studios front and back, solve problems for your co-workers, and get those promotions! It''s a condensed LEGO Studios experience, starring you and Steven Spielberg.' FROM games WHERE igdb_id = 125320 ON CONFLICT (game_id, language_code) DO NOTHING;
