INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('soccer-manager--3', 393490, '2002-09-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobp47.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5hrd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soccer Manager', '"Soccer Manager" is a sports simulation game where you choose your club, take on the role of trainer and manager and guide your team to fame and fortune. Buy and sell your players skilfully, train wisely, negotiate advertising contracts profitably, and select a winning team. In designing this game, we put particular emphasis on making it easy to play with an intuitive interface. For example, there is no calendar. Each change you make takes immediate effect. In real life, stadiums are not built in a day and transfers are not instant - but we feel this makes the game more enjoyable as you learn the skills to lead your club to success. Your activities in "Soccer Manager" are focused on the fundamental areas that have the greatest impact on your club. Your team is the most important thing, so we consciously dispensed with snack bars and fan shops. Accept the challenge and turn your favourite club into one of the leading teams in Europe.' FROM games WHERE igdb_id = 393490 ON CONFLICT (game_id, language_code) DO NOTHING;
