INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aero Elite: Combat Academy', 'Aero Elite: Combat Academy is the fourth game in the AeroWing series and is considered a true flight sim game as the planes react as their real world counterparts. There are 60 authentic aircraft to pilot including the Harrier, A-10 Warthog, the Mirage 2000 and the infamous Mig 29 along with helicopters as well. There are 12 different missions areas that are used and features the new "Scramble Mode" where the player is instructed to intercept a random intruder and identify and land or attack if instructed. There are multiple missions to participate in including interceptions of enemy squadrons and even mastering aerial stunt maneuvers.' FROM games WHERE igdb_id = 19711 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 19711 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
