INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elixir', 'The starting point of Elixir is an ancient prophecy about a long extinct tribe, the Ingoles, which were brutally murdered by the humans. The prophecy says that their god will be reborn as girl to revenge his people. The evil king Ektele Ulka kills all children, but Elixir, a baby with the gift of magic, manages to escape. Now she travels through the country with her friends and tries to survive.' FROM games WHERE igdb_id = 145607 ON CONFLICT (game_id, language_code) DO NOTHING;
