INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('baby-einstein-baby-newton-fun-with-shapes', 165372, '2002-12-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3p5v.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baby Einstein: Baby Newton Fun With Shapes', 'Baby Newton Fun with Shapes helps teach children about basic real-world shapes. Loveable Baby Newton leads the way through five fascinating activities filled with sights, sounds, and words. Vibrant colors, exciting motion, music, and familiar objects keep babies interested. Personalize playtime by adding photos of family members, pets, and household objects. Two modes of play include Learn mode, which teaches the word for each shape, and Guess mode, which lets babies identify the shape before hearing its name. Parents and babies can enjoy this interactive game, while babies learn about circles, squares, triangles, rectangles, and more!' FROM games WHERE igdb_id = 165372 ON CONFLICT (game_id, language_code) DO NOTHING;
