INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Choro Q HG 3', 'Choro-Q HG 3 (Japanese: チョロQ HG 3) (also known as Gadget Racers in Europe) is a role-playing, racing game for the PS2. It is the sequel to Choro-Q HG 2. It was also slated to be published in North America by Conspiracy Entertainment under the title Road Trip Adventure Avenue but it was cancelled for unknown reasons.' FROM games WHERE igdb_id = 196257 ON CONFLICT (game_id, language_code) DO NOTHING;
