INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doka-chan no Onigokko', 'Doka-chan no Onigokko is a game of tag in which players collect chicks in a maze while running away to avoid being caught by Oni. The stage is cleared when all four chicks are caught within two minutes, but the game is over if you get caught by a Oni or run out of time. The gameplay is fast, although some mazes can be quite aggravating and some chicks quite elusive.' FROM games WHERE igdb_id = 234039 ON CONFLICT (game_id, language_code) DO NOTHING;
