INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('simple-2000-series-vol-19-the-renai-simulation-watashi-ni-oma-cafe', 70431, '2002-12-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4igu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sch6ze.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Vol. 19: The Renai Simulation - Watashi ni Oma Cafe', 'Simple 2000 Series Vol. 019: The Renai Simulation - Renai Kissa Watashi ni Oma Cafe is a mix between a simulation and an adventure game. The game begins when the parents of the main character shuffle died in a car accident, so now he is left in charge of the family coffee shop. The game now got some different part since the player has to manage the eatery and the waitresses, all of whom are lovely and potential love interests. During each week he has to decide about the coffee shop menus, the prices, what will be the waitress duties during that week and also what he is going to do that week (he can study management, rest, etc.). There are some times during each week that the player is giving some choices (like in all visual novel adventures) and depending of them the game ending will be different. If he got success he can buy new coffee shops, new waitress dresses, etc.' FROM games WHERE igdb_id = 70431 ON CONFLICT (game_id, language_code) DO NOTHING;
