INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reveal Fantasia', 'Reveal Fantasia Is a Fantasy role playing video game released in 2002 for the PlayStation 2 console by Victor Interactive Software, Inc. in Japan. The game involved an innovative concept of a role playing game involving no battles or fighting. Its game play shows some influence from dating simulation games.' FROM games WHERE igdb_id = 112136 ON CONFLICT (game_id, language_code) DO NOTHING;
