INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thomas & Friends: Building the New Line', 'Sodor comes to life on tracks YOU design and build! The Island of Sodor is busier than ever! The Fat Controller needs your help to build new tracks so Thomas and his Friends can be Really Useful - and keep things running right on time. Choose your favourite engine - Thomas, James, Edward or Percy, build and customise your track layout, then click into "Play" mode and watch as your creation comes to life on-screen. There is plenty of work to be done and surprises around every corner!' FROM games WHERE igdb_id = 23780 ON CONFLICT (game_id, language_code) DO NOTHING;
