INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabela''s Big Game Hunter', 'Back of box information: Advanced Animal Behavior - Game design and animal movement based on actual DNR research, including sight, speed, daily routines and feeding patterns for authentic gameplay action! Special in-game features include - Bullet-Cam allows you to see your shot travel to its destination, scoring system and MUCH, MUCH MORE! Hunt all over North America - You will be mesmerized by the detail and expansive landscapes in 32 different locations that accurately reflect the natural environments from the Northwest Territory to West Texas. Authentic Weapons and Gear - Your hunting experience will be complete as you choose from a wide selection of today''s best-selling firearms, bows, scents, clothes, stands, blinds, ATVs, boats and trucks.' FROM games WHERE igdb_id = 43250 ON CONFLICT (game_id, language_code) DO NOTHING;
