INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Megami Tensei II', 'Following the remake of the first game, Shin Megami Tensei II is a revamped version of the original Super Famicom sequel with improved graphics and gameplay along with a new difficulty mode. The gameplay uses first-person navigation of dungeons and turn-based battles against demons. The player can recruit demons as allies by talking to them rather than fighting them, and two to three demons can be fused to create new demons.' FROM games WHERE igdb_id = 252800 ON CONFLICT (game_id, language_code) DO NOTHING;
