INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Piece: Grand Battle! 2', 'From TV Animation One Piece: Grand Battle! 2 is a Japan-exclusive fighting game for the PlayStation developed by Ganbarion and published by Bandai in 2002. It is the second game in the One Piece: Grand Battle! series and the seventh game to be based on the One Piece Manga and Anime. Similar to the first game, this game uses the song "We Are!" from the One Piece Anime.' FROM games WHERE igdb_id = 75743 ON CONFLICT (game_id, language_code) DO NOTHING;
