INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gourmet Action Game: Manpuku!! Nabe Kazoku', 'Gourmet Action Game - Manpuku!! Nabe Kazoku is another cooking game from Media Entertainment, like Yakiniku Bugyou. This one''s a good deal simpler than even that simple game, as you don''t have to worry yourself over placing the food, flipping it halfway, or judging when it''s done: you just wait for the food to drop into the broiling bowl, then wait for "OK" to appear over it, then you click on it to dish it into your character''s mouth. Munch!' FROM games WHERE igdb_id = 284159 ON CONFLICT (game_id, language_code) DO NOTHING;
