INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Ghouls ''n Ghosts', 'The Game Boy Advance version of Super Ghouls ''n Ghosts includes an "Arrange" Mode not present in the original. The Arrange Mode lacks a second run, so the Goddess'' Bracelet can be obtained anytime when Arthur is equipped with the Golden Armor. Both modes contain a new Save feature, letting the player resume at the last checkpoint with whichever armor and weapon they had equipped. Arrange Mode also features new routes and new bosses' FROM games WHERE igdb_id = 219488 ON CONFLICT (game_id, language_code) DO NOTHING;
