INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('usa-racer', 62146, '2002-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6hpp.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'USA Racer', 'A clandestine group has been organizing illegal street races in the USA for more than 50 years. What started as a fun event has grown into an annual contest for cash and glory. Only six are given a chance to prove their worth. US Racer contains 11 tracks in different locations across the USA. Players can race in cities such as Los Angeles, New York or Washington DC or can take part in a race through the Grand Canyon or Yellowstone. Next to Time Trial and Single Race, the Tournament is the main event. It has been split up in three sections: Park Trial, City Trial and US Race. After completing a section, the next one is opened up. The tracks contain obstacles and jumps. Enemies will try to push other cars off the road, and the police also make an appearance. Scattered around the tracks are power-ups that repair the car, provide boost or cash. The money can be used to upgrade the car, repair it or buy boost prior to the race. After completing an entire tournament with a certain car, an alternate vehicle becomes available for that character. In the Windows version two-player duels are available over LAN or TCP/IP. Players can either go head-to-head or play a game of Cop vs. Racer.' FROM games WHERE igdb_id = 62146 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 62146 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
