INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('luta-de-gladiadores', 291625, '2002-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7wfr.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Luta de Gladiadores', 'It was a dark time forged in blood and steel. The people gathered in arenas to watch violent battles, where only real warriors were able to survive. Amid all this chaos, a story of valor and courage began. Titus, the great fighter, surprised the empire and managed to defeat all the gladiators to be released. The game is a series of one on one gladiator fights with increasingly stronger opponents. Between each fight there is a text screen with a description of the next oponnent which also serves to advance the story. Winning each fight unlocks progress towards the next weapon, which can be equipped for the next fight. The player can move forward, backwards, raise the shield or attack, all in real time. The strategy is to know when to defend and when to attack.' FROM games WHERE igdb_id = 291625 ON CONFLICT (game_id, language_code) DO NOTHING;
