INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sabrina-the-teenage-witch-potion-commotion', 49430, '2002-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2d0q.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sabrina the Teenage Witch: Potion Commotion', 'Sabrina The Teenage Witch: Potion Commotion is a classic style side-scrolling adventure game for all ages based on the popular television series starring Melissa Joan Hart. In Sabrina The Teenage Witch: Potion Commotion, you play as Sabrina, and with the help of your faithful cat Salem you set out to save your aunt Hilda who has accidentally petrified herself. Featuring four levels of gameplay and a humorous story inspired by Viacom Productions television series In Sabrina The Teenage Witch: Potion Commotion for the Game Boy Advance players will explore 4 different worlds including, her Aunt?s house, the school, the pizzeria and the giant family tree. The adventure through Sabrina?s universe will require using magic and fast reflexes to return the world to normal and save the day.' FROM games WHERE igdb_id = 49430 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 49430 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
