INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('big-bass-fishing', 43880, '2002-06-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/es1np2zn0enr1zhqstuu.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Bass Fishing', 'There''s nothing like the real thrill of luring in a largemouth bass, and now you can have the experience without getting a drop of water on you. Try to reel in 14 different types of freshwater fish including spotted bass, redeye bass, and rock bass in this PSX classic, enjoying a dozen massive locales. Real-life obstacles like rod direction, reel speed, and water structures will provide plenty to overcome, but you''ll arrive armed with 20 unique lures to help get the job done. Choosing from a selection of spinners, bucktails, bass bugs, and other stuff that will help get those fishes'' attention, you''ll try to master any of the three impressive modes of play: Free Fishing, Three-day Tournament, and Beat the Clock. Five total events will ensure that the gameplay never repeats itself, and the graphics are downright incredible. It''s not easy to hook and reel a bass, but it sure is fun when you do.' FROM games WHERE igdb_id = 43880 ON CONFLICT (game_id, language_code) DO NOTHING;
