INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('marios-cement-factory--2', 231746, '2002-10-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co60nw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar22rm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario''s Cement Factory', 'The Modern version of the game has Mario working in a cookie factory. Yoshi and Toad are featured instead of the drivers, with Yoshi eating the Yoshi Cookies made on the left conveyor belt and Toad packaging the Yoshi Cookies made on the right conveyor belt. Boos also occasionally appear, taking up cookie dough slots on the second floor. Unlike in Classic Mode, however, Mario is allowed to fall down onto an elevator platform, but touching the very bottom or top still earns the player a miss. When Mario amasses 200, 500, and 700 points, a heart appears for him to remove a miss. Music is also featured in this version, with the tempo changing depending on the speed of the game.' FROM games WHERE igdb_id = 231746 ON CONFLICT (game_id, language_code) DO NOTHING;
