INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Trucks Racing', 'Developed by the same team responsible for the MTV Music Generator series, Super Trucks Racing is a truck-based driving title that offers every official Super Trucks driver, sponsor, circuit, logo, and locations from the 2002 season. Its most renowned feature, however, is likely its physics engine; which is definitely among the most realistic of the time.' FROM games WHERE igdb_id = 43352 ON CONFLICT (game_id, language_code) DO NOTHING;
