INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Excite Bowling', '"Excite Bowling" is an experience game released by Epoch in 2002. It was released as one of the "experimental games" (Taikan game) series. It is a hardware-integrated plug-and-play game that uses XaviX technology. Later, "XaviX Bowling", which can be said to be the successor software, was released on "XaviXPORT", a hardware dedicated to XaviX technology.' FROM games WHERE igdb_id = 262758 ON CONFLICT (game_id, language_code) DO NOTHING;
