INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Test Drive', 'Test Drive is a racing game developed by Pitbull Syndicate. In Test Drive, you play as Dennis Black, a street racer who is contacted by a wheelchair-bound man and hired to race in his place in a series of underground street races known as "test drives". This edition of Test Drive has some improvements over it''s predecessor, Test Drive 6. This time around there is a story driven mode, called "The Underground." You take the role of Dennis Black, an independent street racer who improves his standing in the underground street racing world with the help of a mysterious benefactor.' FROM games WHERE igdb_id = 78193 ON CONFLICT (game_id, language_code) DO NOTHING;
