INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neocron', 'Neocron is a 2002 post-apocalyptic cyberpunk massively multiplayer online role playing game (MMORPG) developed by Reakktor Media GmbH (based in Hannover, Germany) and published by cdv Software Entertainment. It is considered the first cyberpunk-genre MMORPG, and is designed to integrate elements of first-person shooter games. Its 2004 sequel, Neocron 2: Beyond Dome of York, was originally slated to be an expansion pack and released separately under a new publisher, 10tacle Studios AG. Following a brief transitional period where Neocron players were encouraged to transfer their characters to Neocron 2, the Neocron servers were closed while the Neocron 2 servers continue to run.' FROM games WHERE igdb_id = 19706 ON CONFLICT (game_id, language_code) DO NOTHING;
