INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gran Turismo Concept: 2001 Tokyo', 'Gran Turismo Concept is a racing video game in the Gran Turismo series. It is essentially a short version of Gran Turismo 3: A-Spec intended as a preview for the full release of the game. For undisclosed reasons, the game was not released in the North American market, although a stripped-down version of it was released in form of Gran Turismo: Nissan 350Z Edition.' FROM games WHERE igdb_id = 80163 ON CONFLICT (game_id, language_code) DO NOTHING;
