INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Justice League: Injustice for All', 'Justice League: Injustice for All is a 2002 video game developed by Saffire and published by Midway Games for the Game Boy Advance. The game is based on the Justice League animated television series and showcases the League''s seven members within the context of a side-scrolling beat ''em up with platforming elements. The plot centres on the League''s efforts to avert global catastrophe carried out by Lex Luthor''s Injustice Gang.' FROM games WHERE igdb_id = 6484 ON CONFLICT (game_id, language_code) DO NOTHING;
