INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saru! Get You! 2: Ukki Ukki Disc', 'The disc contains three slide puzzles that, when completed, unlock the "Saru-Buster" gadget, which is basically just a land version of the Water net. Due to the "Ukki-Ukki" disc not being released outside of Japan, this gadget is not available for Jimmy/Hikaru to use in the international versions.' FROM games WHERE igdb_id = 386769 ON CONFLICT (game_id, language_code) DO NOTHING;
