INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Vol. 13: The Renai Adventure 2 - Garasu no Mori', 'Simple 2000 Series Vol. 013: The Renai Adventure 2 - Garasu No Mori: Glass no Mori is a PS2 otome game developed by HuneX and published by D3. The game is volume 13 of the Simple Series line of budget games. The game tells the story of the protagonist''s last visit to her deceased grandfather''s house on the edge of a haunted forest in the countryside. The forest is rumoured to be a ''kamikakushi'' that steals away children.' FROM games WHERE igdb_id = 70556 ON CONFLICT (game_id, language_code) DO NOTHING;
