INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Groove Adventure Rave', 'Released only in Japan, Groove Adventure Rave is the first action RPG game based on the Rave Master manga series written and illustrated by Hiro Mashima. This action RPG includes a original story with a new character created by the original author Mashima-sensei, featuring the RPD system where your companions trust changes based on the aciton you make.' FROM games WHERE igdb_id = 69328 ON CONFLICT (game_id, language_code) DO NOTHING;
