INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ngt-next-generation-tennis', 49320, '2002-08-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co86cv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scs4yu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NGT: Next Generation Tennis', 'Playing Next Generation Tennis is like playing a match and watching it live on TV at the same time, with slow motion replays, umpire announcements, realistic player behaviour and crowd noise all adding that touch of authenticity. With over 10 game modes (including 4 hidden ones), Next Generation Tennis offers a broad palette of pleasures, from the most classic to the most innovative. Thanks to the help of the teams at Roland Garros and the US Open, who provided exact plans of their stadiums, the development team were able to produce faithfully accurate models of the most famous courts at Roland Garros and the US Open, as well as of 6 other courts with different surfaces (grass, synthetic). The players must prove themselves on the authentic courts of these world-famous tournaments, in front of crowds who react to their performance.' FROM games WHERE igdb_id = 49320 ON CONFLICT (game_id, language_code) DO NOTHING;
