INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Progress Quest', 'Progress Quest is a video game developed by Eric Fredricksen as a parody of EverQuest and other massively multiplayer online role-playing games. It is loosely considered a zero-player game, in the sense that once the player has set up their artificial character, there is no user interaction at all; the game "plays" itself, with the human player as spectator.' FROM games WHERE igdb_id = 94363 ON CONFLICT (game_id, language_code) DO NOTHING;
