INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Myth of Ambition', 'Myth of Ambition is a turn-based strategy game about gang wars in the capital of colonial Korea. The player chooses a scenario between 1931 and 1945 and a main character, before fighting for dominance in Seoul. The game involves personnel and resource management, administration of territories and tactical brawls between gang members.' FROM games WHERE igdb_id = 114139 ON CONFLICT (game_id, language_code) DO NOTHING;
