INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbie as Rapunzel: A Creative Adventure', 'Barbie plays Rapunzel. A witch has turned Prince Stefan to stone and destroyed much of the castle, all for the offense of not being invited to the masquerade ball. Rapunzel and her dragon friend, Penelope, set out to restore the castle in time for the ball and find missing magic gems to restore the prince.' FROM games WHERE igdb_id = 23781 ON CONFLICT (game_id, language_code) DO NOTHING;
