INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fatman Adventures', 'The game puts you in control of Fatman, a treasure hunter who discovers a mystery forest mentioned in ancient legends. On his way to collecting all the treasure of the sacred woods Fatman will have to face cruel monsters guarding precious diamonds and rubies. Fatman will have to outsmart his enemies by digging traps-holes, setting cage-traps and using magic items.' FROM games WHERE igdb_id = 250229 ON CONFLICT (game_id, language_code) DO NOTHING;
