INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jonah: A VeggieTales Game', 'Israel''s No. 1 prophet, Jonah, has a great job delivering God''s messages. But when Jonah gets the call to go to Nineveh, he runs away--straight into a whale-full of trouble. Join Jonah (played by Archibald Asparagus) and Khalil the caterpillar on the voyage of a lifetime, from a stormy ride on a pirate ship to the belly of a whale, and across the desert to the city of Nineveh--where the people are so nasty, they slap each other with fishes.' FROM games WHERE igdb_id = 80600 ON CONFLICT (game_id, language_code) DO NOTHING;
