INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'V-Master Cross', 'V-Master Cross is an isometric turn-based RPG released only in Japan. The main hero is a young boy who was transported into a weird magic world. The gameplay is based on a special card fight - the battlefield is divided into squares (5 fields for each player), on which the player can summon monsters from a specific deck of cards, with some that can only be placed on a specific field. Each summoned monster has its own look and stats.' FROM games WHERE igdb_id = 240903 ON CONFLICT (game_id, language_code) DO NOTHING;
