INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Santa Clicker Tycoon', 'You are Santa and it is your job to make enough presents to make everyone happy during Christmas. The virus hit Santa hard, as he has lost his entire workforce. So you must start from scratch, and make sure everyone has a happy Christmas. Luckily you will be able to hire new elves, and other things, with your newly created presents.' FROM games WHERE igdb_id = 209630 ON CONFLICT (game_id, language_code) DO NOTHING;
