INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heróis e Vampiros', 'Heróis e Vampiros was a multiplayer Trading Card Game designed to complement the release of the vampire-themed telenovela O Beijo do Vampiro. In this card game, players could discover hints from the TV show to obtain special cards and abilities. Conversely, specific in-game events also impacted the storyline of the TV series, mirroring the dynamic struggle between Good and Evil portrayed both on screen and within the gaming world.' FROM games WHERE igdb_id = 93240 ON CONFLICT (game_id, language_code) DO NOTHING;
