INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GTC: Africa', 'GTC: Africa combines the endurance of rally-style driving with the rush of competitive circuit racing. Journey through the most exotic locations on the African continent in officially licensed vehicles from Ford, Mitsubishi, Subaru, and Pontiac. The game features 19 different circuits in locales ranging from safari treks and lagoons to countryside vistas and jungles. In both single-player and multiplayer modes, you must powerslide through rugged terrain, climb towering hills, and improve your track times to achieve victory.' FROM games WHERE igdb_id = 43598 ON CONFLICT (game_id, language_code) DO NOTHING;
