INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Tennis WTA Tour', 'Take to the court and experience the realism and authenticity of WTA Tour Tennis. First, choose one of 20 professional tennis players such as Serena Williams, Martina Hingis, and Jelina Dokic--each with lifelike facial expressions and movements. Then, engage in fast-paced competition on grass, clay, and hard surfaces. With simple controls, multiple levels of difficulty, and AI based on actual player attributes, WTA Tour Tennis challenges both newcomers and seasoned pros alike.' FROM games WHERE igdb_id = 26024 ON CONFLICT (game_id, language_code) DO NOTHING;
