INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Treasure Planet: Treasure Racer', 'Treasure Planet: Treasure Racer is one of the three games from the Treasure Planet: Training Academy collection that was distributed by McDonald''s Mighty Kid''s Meals, the other two being Treasure Planet: Broadside Blast and Treasure Planet: Etherium Rescue. Treasure Racer was published by Disney Interactive and released in 2002, along with all the other Treasure Planet related games.' FROM games WHERE igdb_id = 213025 ON CONFLICT (game_id, language_code) DO NOTHING;
