INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medarot G: Kuwagata Version', 'Medarot G is a 2D action game released in 2002 for the Game Boy Advance. It was the first Medarot action game to be released in Japan. In the Kuwagata version the player starts with Adolphin. The game mainly features characters and Medarots from Medarot 5, but some major characters from Medarot 2 also make an appearance. The gameplay and battle system were also used in Medabots AX, which was released in North America a month earlier.' FROM games WHERE igdb_id = 79757 ON CONFLICT (game_id, language_code) DO NOTHING;
