INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nba-inside-drive-2003', 47358, '2002-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/b1wnlomgosvvn1eyuswi.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Inside Drive 2003', 'Inside Drive is solid on almost every front except for some aspects of the offensive game, the most notable problem being the inability to pass out of layups or similar moves to the basket. One of the most important aspects of professional basketball is being able to drive to the lane and have a player make it look like he''s going up for a shot so that he can draw defense, but then pass the ball to an open man on the inside or to a wide-open player out on the perimeter. Indeed, generally driving through the lane can be a little problematic since the AI tends to latch onto players in the paint, and the juke moves can be difficult to use effectively against tough opponents.' FROM games WHERE igdb_id = 47358 ON CONFLICT (game_id, language_code) DO NOTHING;
