INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NCAA March Madness 2003', 'Do you dream of cutting down the net in New Orleans? Now you can experience the thrill of being the National Champ with NCAA? March Madness? 2003 -- the ultimate college basketball experience. From the crazed fans in the stands, to the mascots on the court and the fight songs played in the arenas, NCAA March Madness 2003 captures the spirit, excitement and rivalry that is college basketball.' FROM games WHERE igdb_id = 43271 ON CONFLICT (game_id, language_code) DO NOTHING;
