INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ikinari Happy Bell', 'Main character is a student who has just received inheritance from his deceased father. But instead of huge assets all he gets is a mansion bought with mortgage and many debts. When he attends the mansion, there is a maid who claims to be here to handle his engagement and five girls that are prepared by father for his son...' FROM games WHERE igdb_id = 77757 ON CONFLICT (game_id, language_code) DO NOTHING;
