INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghost ''n Goblins Exceed', 'Ghost ''n Goblins Exceed is a freeware remake of the classical Capcom game. You are an angry little mouse that defeats enemies by setting bombs or simple jump over them. The game features four different stages with end bosses and different themes.' FROM games WHERE igdb_id = 138295 ON CONFLICT (game_id, language_code) DO NOTHING;
