INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dexter''s Lab: Dee Dee''s Moon Squad', 'To prevent anymore trouble, Dexter has transported Dee-Dee, Mee-Mee and Lee-Lee to the moon. The three girls are forced to use a moon buggy to find a rocket ship that will take them back home. The player must traverse the moon buggy across ten levels, avoiding pitfalls and battling aliens along the way. The buggy can jump, fire photon projectiles and launch tracking missiles.' FROM games WHERE igdb_id = 203085 ON CONFLICT (game_id, language_code) DO NOTHING;
