INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Berry Tree', 'Berry Tree is a Pokémon e-Reader game for the Game Boy Advance. In order to play Berry Tree four different Pokemon cards must be scanned. The cards are: Nidoqueen (#22), Gligar (#59), Growlithe (#62), and Ursaring (#110). The object in Berry Tree is to shake as many berries out of the trees as possible. A set of button prompts will show up at the bottom of the screen. Afterwards the player will be given a set amount of time to copy the buttons displayed.' FROM games WHERE igdb_id = 68726 ON CONFLICT (game_id, language_code) DO NOTHING;
