INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Runabout 3: Neo Age', 'Go anywhere, smash anything that gets in your way. It''s not always about driving well in New York - sometimes it''s about getting from A to B by any means. If it involves taking out a few cars, buses, fire engines, taxis, delivery vans, telephone boxes, jumping a few ramps, making a few shortcuts... then so be it!' FROM games WHERE igdb_id = 43599 ON CONFLICT (game_id, language_code) DO NOTHING;
