INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donald Trump''s Real Estate Tycoon', 'One of the modern world''s most famous entrepreneurs offers gamers the role of an international mogul in Donald Trump''s Real-Estate Tycoon. The overall goal of the game is to unseat Trump himself as the most influential magnate on the planet. Players must find the best building site in which to found their business empires, choosing from locations in New York, Los Angeles, Atlantic City, London, and Paris. Design an office space layout to appeal to high-rent tenants and keep things running smoothly by hiring maintenance personnel.' FROM games WHERE igdb_id = 25706 ON CONFLICT (game_id, language_code) DO NOTHING;
