INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aces of World War 1', 'Aces of World War I is an action flight simulator set in World War I. It contains more than 40 missions in a recreated area of 1,000 square kilometers. The objectives of the missions are, for example: air battles, the destruction of balloons or convoys and attacks on ground targets and boats. Weather effects and two different difficulty levels are included.' FROM games WHERE igdb_id = 205967 ON CONFLICT (game_id, language_code) DO NOTHING;
