INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Surveillance Kanshisha', 'Surveillance Kanshisha is a First-Party PlayStation 2 Adventure Science fiction interactive game published by Sony Computer Entertainment Japan with animation created by Production I.G. It takes place in the 2050s where a United Nations-created special forces unit called Shadow Sword is deployed to protect the Earth-Mars travel route from anti-UN terrorists called Neo Kleit, conducting terrorist attacks to remove the UN''s control of the space program. A special public security surveillance network is unveiled for the first time called Project Surveillance, which is used to assist Shadow Sword operatives in their work in apprehending and hunting down the terrorists.' FROM games WHERE igdb_id = 65021 ON CONFLICT (game_id, language_code) DO NOTHING;
