INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tombstone 1882', 'A budget priced RTS set in the wild west. Players choose a side in the famous Earp/Clanton feud and set about harvesting wood and mining silver to construct the buildings and hire the fighters needed to defeat the other. There are approximately 20 total scenarios (although all take place on the exact same map) with each side having access to the same six types of buildings and five types of units.' FROM games WHERE igdb_id = 93293 ON CONFLICT (game_id, language_code) DO NOTHING;
