INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmic Batter Defense', 'Strike out means the human extinction. Swing your bat to save the Earth! The Hugest War of the World on your palm. The alien UFOs fire at the earth. You hit back those attacks with the bat, and defeat them. A strikeout means geocide. World''s fate depends on your bat. Enjoy the throb stomach mind of the space scale, by simple screen tappings.' FROM games WHERE igdb_id = 205993 ON CONFLICT (game_id, language_code) DO NOTHING;
