INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lethal-skies-elite-pilot-team-sw', 26746, '2002-05-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1own.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lrraqbocm6na4pztwtv1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lethal Skies Elite Pilot: Team SW', 'When the ice in the Siberian region melts, a worldwide catastrophe occurs and 90% of the earth is submerged under water. Lifting the major cities and providing assistance is the objective of the newly formed World Alliance, comprised of most of the surviving nations. Opposing the World Alliance are terrorist and militant countries who banded together under WORF (World Order Reorganization Front) looking to profit from the disaster. With global war imminent, the World Alliance organizes a multi-national military organization known as Frontier Nations and its air force, Team SW.  Lethal Skies: Elite Pilot: Team SW is a realistic combat flight simulator for the single player. It features vibration and G-force effects, 2 cockpit views as well as 3rd person and full screen, mid-air refuelling (in certain situations), 14 different missiles for air-to-air and air-to-ground battles, radar, and GPS. Change pilots, planes and weapons in the Hangar. Depending upon the scenario, take off from runways or aircraft carriers. Select Replay to view completed, saved missions.  The Training Modes are:  Mission - take offs and landing, air-to-air attack, air-to-ground attack, combination  Dogfight - simulated battles against the computer (one-on-one to four-on-four)  Free Flight - fly freely in different stages without enemy confrontation  The heart of the game takes place in Campaign Mode which has 20 missions selected from a world map. A preliminary briefing and information about the enemy is provided for each mission.  Choose to control these fighter planes:  F-14D Super Tomcat  F-16 Fighting Falcon  F/A-18E Super Hornet  F-15E Strike Eagle  F-22 Raptor  EF2000 Typhoon  JAS39 Gripen  MiG29 Fulcrum  Su27 Flanker' FROM games WHERE igdb_id = 26746 ON CONFLICT (game_id, language_code) DO NOTHING;
