INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sandmen', 'Sandmen is a free, German 2D point-and-click adventure. You are sleeping and are awakened by some voices who turn out to be sandmen. Since you saw them, they want to take you with them unless you manage get them a person who commits suicide. The game is controlled via the mouse and is inventory based. Aside from the cut-scenes there is no music or sound.' FROM games WHERE igdb_id = 117316 ON CONFLICT (game_id, language_code) DO NOTHING;
