INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('moorhuhn-kart--1', 47070, '2002-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coakhl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vrtkqlgjmx9qgiebcnrh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moorhuhn Kart', 'Moorhuhn''s first venture into the racing genre. This kart racing game features a number of new characters that are to be introduced as members of the Moorhuhn-Family (known from the Moorhuhn shooters). The game features comic-style 3D-graphics, 5 different drivers - each with its own driving style - and 3 different game modes. The whole concept reminds one of the Mario Kart games. The player chooses a character, either Moorhuhn itself or Lesshuhn, Snowman or Pumpkinhead. The game''s objective is to win the race, of course, but your opponent will try everything in their power to keep your chosen character from winning by sending you off the racetrack. To achieve this they resort to things like weights, water bombs, chewing gum, boards larded with nails or even rockets. But the player can also find these so called power-ups, small packages that can be found at random order on the racetrack. Unfortunately, you do not know what is in the packages until they are opened which adds a little surprise to the action. The kart is controlled using the arrow keys on the keyboard, but one can also use a Windows compatible gamepad. The XL version lacks the Duel mode and two courses.' FROM games WHERE igdb_id = 47070 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 47070 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
