INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Micro Commandos', 'Micro Commandos is a real time strategy game where you control tiny aliens from another planet look for a so called "Ultimate Weapon". Lead your aliens through 14 missions in the world of the big people. Explore unusual settings like a museum, subway, pizzeria....Collect resourse''s of food and material to feed and construct vehicles and buildings for your aliens. Fight off another alien race looking for the Ultimate Weapon as well as bugs hamsters and the family cat.' FROM games WHERE igdb_id = 71460 ON CONFLICT (game_id, language_code) DO NOTHING;
