INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harshlands', 'The Harshlands MUD is, above all else, a role-playing game world. The game should be viewed in most ways as a traditional sit-down, pencil and paper, role-playing game, and not as a video game where the object is to tally the most kills. You can become better at your chosen trade, buy/sell, travel, fight, get a job and the scope is pretty much endless.' FROM games WHERE igdb_id = 228879 ON CONFLICT (game_id, language_code) DO NOTHING;
