INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gal Pani X', 'A Qix clone in vein of Gals'' Panic, where one must draw lines in the screen to unveil images featuring fanart of characters from To Heart. Unlike Gals'' Panic, the images are not sexually explicit, though some are suggestive. In addition, it features other additions to the Qix formula, such as the ability to move diagonally and bullet hell elements.' FROM games WHERE igdb_id = 250208 ON CONFLICT (game_id, language_code) DO NOTHING;
