INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Bounce Out', 'Super Bounce Out! is a single player, shareware, tile matching game In this game the tiles are balls and they descend from the top of the screen. The player uses the mouse to swap adjacent balls to make rows of three or more, such rows disappear, the remaining balls fall down and new balls are added. Black balls if/when they appear cannot be swapped with anything. The objective is to clear a specified number of balls on each level within a time limit, as the player progresses the time limit gets shorter.' FROM games WHERE igdb_id = 53685 ON CONFLICT (game_id, language_code) DO NOTHING;
