INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mobile-suit-gundam-gihrens-greed-zeon-revolutionary-war', 75727, '2002-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9del.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mobile Suit Gundam Gihren''s Greed: Zeon Revolutionary War', 'War for Zeon Independence adds an updated map system and military system to a rewritten script, several new characters, an updated spying system and Mobile Suits from MSV. The battles are fought in full 3D, unlike previous titles in the series. However, this installment omits the Zeta Gundam era conflicts featured in Blood of Zeon. As a result, the Principality of Zeon and the Earth Federation are the only factions featured in this entry. However, after completion of the game with each team, an option to use them in IF mode is unlocked. Each completion of the game increases the player''s "IF" Level and more points to use in IF Mode. IF Mode allows the player to create their own team; Choosing such options as a leader (or creating their own leader), Their home base, which officers to start with, which technology group their faction is in and what units the player starts with. This also comes with a variety of Scenarioes to play through, with preset IF modes.' FROM games WHERE igdb_id = 75727 ON CONFLICT (game_id, language_code) DO NOTHING;
