INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('monopoly-party', 4016, '2002-10-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7md8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq4a7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monopoly Party', 'The Monopoly Party game is the fastest way to discover what your friends are really like. It''s an intense buying, trading, building, and deal-making frenzy because every player moves at the same time. Here''s how it works: Everyone rolls a set of dice at the same time. As soon as everyone rolls, everyone moves. Just roll and go. Then do all of the things you love, such as buy property, pass "Go," and draw cards from "Community Chest." Play Monopoly Party and find out who will cut you a deal when the chips are down and who will bankrupt you out of the game.' FROM games WHERE igdb_id = 4016 ON CONFLICT (game_id, language_code) DO NOTHING;
