INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Book of Pooh: A Story Without a Tail', 'Playhouse Disney''s The Book of Pooh: A Story Without a Tail is based on a Disney television series that is in turn based on characters created by the author A. A. Milne. The characters in the game are animated to resemble the Bunraku puppetry style of the series. As the game begins, Pooh and his friends are gathered in the Hundred Acre Wood discussing the fine-ness of the day when Eeyore announces he has lost his tail. The friends quickly offer to help him find it, and the player can select any of five characters to set off on a search.' FROM games WHERE igdb_id = 72135 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 72135 AND c.slug = 'disney-interactive' ON CONFLICT DO NOTHING;
