INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dual Blades', 'It is 150 B.C. amidst the Hun Empire. You must possess the power to slay your enemies and execute insane combos. The fearsome Alperen has harnessed incredible energy by merging his soul and the immortal sword to create the legendary weapon of Dual Blades. Survive battle after battle and face the ultimate test to topple Alperen, gain the sword and become immortal!' FROM games WHERE igdb_id = 6392 ON CONFLICT (game_id, language_code) DO NOTHING;
