INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spirit: Stallion of the Cimarron', 'Based on the film of the same name, Spirit: Stallion of the Cimarron tells the tale of a rambunctious mustang stallion named Spirit and his journey through the untamed American West. A sudden and violent thunderstorm has hit Homeland and scattered the herd. Even Spirit is nowhere to be found. Luckily, Little Creek and Little Brook know of the lost horses and have set out to help them return to Homeland. Only you can help them get the herd home safely and find out what has happened to Spirit.' FROM games WHERE igdb_id = 49257 ON CONFLICT (game_id, language_code) DO NOTHING;
