INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('billiards-with-pilot-brothers-comments', 119438, '2002-09-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1m23.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6mdk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Billiards with Pilot Brothers comments', 'A unique atmosphere, lively warmth of the fireplace, soft play of light on ivory, a sense of competition with an opponent and original comments from the well-known Pilot Brothers...  Billiards is like a play that talented actors play in new ways every time. Only those who have never held a cue in their hands can consider it a boring game. Or those who have no sense of excitement at all.  American, pyramid, pool - try your hand at any of the three types of billiards - both beginners and experienced players are waiting for the most unexpected discoveries! After all, billiards is not just the rules and technique of the game. Its laws, its etiquette, its secrets rule here...' FROM games WHERE igdb_id = 119438 ON CONFLICT (game_id, language_code) DO NOTHING;
