INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbie Beauty Styler', 'Barbie Beauty Styler is a creative painting / drawing package featuring Barbie and her friends Teresa, Kira and Christie. It is aimed at the younger gamer. There is very little writing, all the icons ''speak'' to identify themselves as the mouse passes over them and the game regularly chips in with encouraging comments like ''You''re really good at this'' and ''Isn''t this fun!''.' FROM games WHERE igdb_id = 200601 ON CONFLICT (game_id, language_code) DO NOTHING;
