INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ReVolution', 'A futuristic first person shooter where a mega corporation (known as ''The Corporation'') seems to have taken over every facet of life. You start the game as a new janitor for The Corporation. Before long however, you find out that the corporation is up to no good. You then join the resistance (known as... you guessed it: ''The Resistance'').' FROM games WHERE igdb_id = 73967 ON CONFLICT (game_id, language_code) DO NOTHING;
