INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jim Henson''s Bear in the Big Blue House', 'Based on the TV show of the same name, Bear in the Big Blue House invites players to Ojo''s birthday party. The goal is to help Ojo find her presents. To do so, the player must participate in eleven mini-games, each having two difficulty levels. There are two ways to explore and play, Adventure Mode and Activity Mode. The game is aimed at younger players.' FROM games WHERE igdb_id = 49914 ON CONFLICT (game_id, language_code) DO NOTHING;
