INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'D.C.: Da Capo', 'The game is centered around the protagonist, Asakura Jun''ichi, who lives on a fictional japanese island named Hatsunejima peacefully attending the local Kazami Academy. His childhood friend and cousin, Yoshino Sakura, returns to the island Hatsunejima after moving to America several years ago. Most of the main stories revolve around the magical unwilting sakura tree, it''s powers and mystical connection to the main characters.' FROM games WHERE igdb_id = 84314 ON CONFLICT (game_id, language_code) DO NOTHING;
