INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tropical America', 'Tropical America is a game that fuses the new world of video games to a compelling past through a journey to unravel the mysteries of the Americas. Your journey begins as the sole survivor of a terrible massacre - you must find four pieces of evidence to bring justice to the memory of your small village. Developed in collaboration with Los Angeles artists, teachers, writers and high school students, the game features a bilingual, thematic gameplay, accompanied by an online database of educational resource materials, source texts and imagery.' FROM games WHERE igdb_id = 173420 ON CONFLICT (game_id, language_code) DO NOTHING;
