INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GT Advance 3: Pro Concept Racing', 'Get behind the wheel of the world''s top rally cars as you span the globe in quest of a championship. Listen to your navigator as he helps you through more than 40 unique tracks spanning different weather and terrain through 14 grueling stages. Fly over jumps or skid around obstacles on your way to the top of the rally racing circut. Link up with a friend using the GBA link cable for amazing head-to-head competition or watch the action again using the replay mode.' FROM games WHERE igdb_id = 6426 ON CONFLICT (game_id, language_code) DO NOTHING;
