INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Defender of the Crown: Digitally Remastered Edition', 'This edition is the first release of Defender of the Crown for Windows / Macintosh and it is a remake of the original game. This digitally remastered edition features enhanced graphics and sound, and additional material. Years later, an original version of the game with original graphics and sounds was also released for Windows, which makes this a remake and a separate game to the regular port of the original MS-DOS version to Windows.' FROM games WHERE igdb_id = 170339 ON CONFLICT (game_id, language_code) DO NOTHING;
