INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sanyo-pachinko-paradise-7-edokko-gen-san', 138539, '2002-06-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9hsy.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sanyo Pachinko Paradise 7: Edokko Gen-san', 'Pachinko Paradise 7 is one of the many titles in Irem''s long-running pachinko simulation series. It features faithful 3D recreations of two pachinko machines made by Sanyo Bussan: CR Edokko Gen-san L7, CR Edokko Gen-san M6. There are two modes available: Tsūjō (Normal) mode allows the player to modify a wide range of settings for each machine, while Jissen (Battle) mode challenges the player to win as many balls as possible on the default settings with a limited starting pool and time limit. There is also a View mode where the various animations that play on the in-game display can be freely viewed. There is no story mode.' FROM games WHERE igdb_id = 138539 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 138539 AND c.slug = 'irem-software-engineering-co' ON CONFLICT DO NOTHING;
