INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster & Me', 'Monster and Me was a 2D MMORPG from NetDragon Websoft and TQ Digital Studio inspired by Chinese myth and culture. Players could find and train over 200 monsters as pets, to fight alongside their characters, or to sell, trade with others, or battle with other players'' monsters. Players could craft their own spells, and the game also featured several minigames. Monster and Me was shut down in June of 2012.' FROM games WHERE igdb_id = 182466 ON CONFLICT (game_id, language_code) DO NOTHING;
