INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Powerpuff Girls: Him and Seek', 'Nothing is what it seems in Townsville! The Powerpuff girls have been sent on a perfectly innocent scavenger hunt by Mrs. Keane until the evil Him steps in with his own version of the game to spice things up! Take control of Blossom Bubbles and Buttercup and defeat the villains solve the mystery and teach Him a lesson once and for all.' FROM games WHERE igdb_id = 49433 ON CONFLICT (game_id, language_code) DO NOTHING;
