INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tom-clancys-rainbow-six-lone-wolf', 44989, '2002-08-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49oe.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Rainbow Six: Lone Wolf', 'Playing as Rainbow Six team member Ding Chavez, players travel to Norway to eliminate a terrorist group planning to destabilize Eastern Europe with illegally smuggled US weapons. In keeping with the "Lone Wolf" mode of Rainbow Six assignments, missions are conducted without the help or hindrance of teammates. Planning phases include briefing, intelligence, kit select, and map screens, while actual gameplay takes place from a first-person perspective. Weapons can be set to fully automatic (continuous), burst (three shots), or semi-automatic (one shot). Crosshair and auto-locking features provide concise control when aiming, though grenades can be used in situations requiring less precise targeting. The mission objectives, a health meter, mini-map, the currently selected weapon, and ammo status are displayed on-screen at all times. Other features in Tom Clancy''s Rainbow Six: Lone Wolf include a choice of insertion points for each mission (with different advantages), night vision goggles, and an option to save after successfully completing each mission.' FROM games WHERE igdb_id = 44989 ON CONFLICT (game_id, language_code) DO NOTHING;
