INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'K-1 Pocket Grand Prix', 'K-1 Pocket Grand Prix is a kickboxing game, published by Konami, which was released in Japan in 2002. K-1 Pocket Grand Prix is a fighting game developed by Daft Co. and published by Konami Corporation for Game Boy Advance. K-1 Pocket Grand Prix is a kickboxing game that uses the K-1 brand and real fighters. Players can choose from one of fourteen different fighters. Players can kick, punch, and use special moves.' FROM games WHERE igdb_id = 49656 ON CONFLICT (game_id, language_code) DO NOTHING;
