INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jazz and Faust', 'Jazz and Faust is an epic adventure game where you can immerse yourself in the role of either seam captain Faust or a smuggler Jazz and embark on a quest for lost treasure and riches in a beautifully rendered 3D environment. Traveling through three ancient worlds, you will communicate with the various inhabitants, thus revealing the game''s story objectives, quests, and puzzles.' FROM games WHERE igdb_id = 127331 ON CONFLICT (game_id, language_code) DO NOTHING;
