INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taxi Challenge: London', 'There are rumours that a competition called the "London Challenge" is soon going to take place, in order to determine who is the best taxi driver in the British capital. In this quasi-sequel to Taxi Challenge Berlin, players start by choosing a traditional Black Cab or one of three sports cars, and then try picking up passengers around town and driving them to their destinations as quickly as possible.' FROM games WHERE igdb_id = 116972 ON CONFLICT (game_id, language_code) DO NOTHING;
