INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kick Off 2002', 'KickOff 2002 brings arcade-style gaming action to the most popular sport on Earth! Go for the goal in this incredible new soccer game!  - Take control of over 200 national teams, all affiliated with FIFA  - All players have a combination of eight skills & attribute stats that decide how they''ll perform on the field -- manage them properly to create a winning team  - Control the actionon the field -- execute complex passing routines, difficult goal shots, and flashy maneuvers  - Game-changing AI adopt their strategy on real game situations  - See how well you can do against another person in exciting 2-player mode' FROM games WHERE igdb_id = 71996 ON CONFLICT (game_id, language_code) DO NOTHING;
