INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sítio do Picapau Amarelo: Geografia de Dona Benta', 'Geografia de Dona Benta tells the story of one of the adventures that took place at Sítio do Picapau Amarelo, in which the Marquês de Rabicó trips and goes flying through the sky on Emília''s magic carpet. Through several games you can take part in a trip around the world, getting to know and learning the main characteristics of each country and city.' FROM games WHERE igdb_id = 286923 ON CONFLICT (game_id, language_code) DO NOTHING;
