INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Styrlitz 3: Agent USSR', 'Styrlitz 3 is a comedic point-and-click adventure game. It is a parody of the popular Soviet television series Seventeen Moments of Spring about the exploits of a Soviet spy operating in Nazi Germany under the name Max Otto von Stierlitz. This is the third game in the series. In this entry in the series, Styrlitz investigated a mysterious crash in space involving the soviet spacecraft with the first woman in space and a UFO.' FROM games WHERE igdb_id = 281656 ON CONFLICT (game_id, language_code) DO NOTHING;
