INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Flintstones: Big Trouble in Bedrock', 'Barney is ancient history unless fred can save him from the most sinister villian of the Stone Age, Dr. Sinister!!! It''s a perilous prehistori world, where finding your best buddy may be the most fun you''ve ever had! You''re the star of the show! The Flintstones characters and classic cartoon action makes you feel like a full fledged member of the modern Stone Age family! Run, jump, judo chop, and double jump your way through danger!' FROM games WHERE igdb_id = 49194 ON CONFLICT (game_id, language_code) DO NOTHING;
