INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('motogp-2--2', 195571, '2002-02-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6zos.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scgd6o.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MotoGP 2', 'Namco, the genius company behind Tekken and Ridge Racer, has also proved itself a dab-hand at the motorcycle racing game. Early 2001, the arcade giant released Moto GP for PlayStation 2, and its runaway success quickly led to the research of a sequel. After considerable development time, Namco return with the second instalment. Moto GP 2 players can expect a glut of updates. New season statistics have naturally been included, and there are now 10 circuits to race on, all of which are genuine true-to-life tracks, bustling with interactivity. The graphics are noticeably better, cleaner, with improved textures and far fewer aliasing troubles. The gameplay is as polished as ever, with easy-to-learn controls, a steady learning curve, and AI that doesn’t make you want to tear your hair out... at least until you reach the later stages of the game. Moto GP 2 also offers the usual Championship and Time Trial mode of play. But, in typical Namco fashion, multiplayer mode is where the majority of the fun is to be had. In the entire history of video games, the ability to play the same game with one or more friends is still one of the most welcome features in a game. Moto GP 2 doesn’t disappoint in this regard. It’s frantic, it gets personal, and that’s what makes it interesting. A grand sequel, all in all. Well worth a look, even if you own the original.' FROM games WHERE igdb_id = 195571 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 195571 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
