INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('klonoa-heroes-densetsu-no-star-medal', 49638, '2002-12-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5b66.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7oe.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Klonoa Heroes: Densetsu no Star Medal', 'This entry in the Klonoa series sees the floppy-eared hero training to become a true hero in a new RPG system. Klonoa Heroes: Densetsu no Star Medal is a spin-off of the Klonoa franchise, released only in Japan on December 13, 2002. Klonoa Heroes was developed by Namco and published by Namco for the Game Boy Advance. Klonoa Heroes is a twist on the traditional Klonoa games, putting Klonoa in a more action role playing game along the lines of Legend of Zelda or Beyond Oasis. The game does have voice acting, as well. Kumiko Watanabe plays Klonoa, Takahiro Sakurai plays Guntz, Shouzou Iizuke plays Pango, and Yutaka Shimaka plays Garlen. Klonoa Heroes'' gameplay is very similar to the gameplay of The Legend of Zelda. Players can control one of three characters (Klonoa, Guntz, and Pango) in a top-down perspective, hitting enemies with various attacks (Klonoa with the Wind Ring seen in the platforming games, albeit with a few differences). Guntz uses a handgun, while Pango throws bombs. In addition, these characters can collect more weapons as the game progresses. Every enemy in the game is given a color (either blue or red), and the player must attack that enemy with the corresponding attack (as each weapon has a blue and red attack). Klonoa Heroes also has role playing aspects. Experience points are gathered by picking up Dream Shards after defeating enemies (failure to pick them up results in no experience). Enemies also drop coins, which can be spent on items and weapons. These items can be found in chests scattered throughout the levels, as well. Most items can be used to restore health, but there are various other uses (such as stat benefits). Leveling up also allows the player to distribute points in several different areas (traditional role playing game stats, such as attack, defense, and agility). These changes are not permanent, and can be changed at any time (when not in the middle of a level).' FROM games WHERE igdb_id = 49638 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 49638 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
