INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bikini-karate-babes', 51236, '2002-08-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gaj.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bikini Karate Babes', 'Bikini Karate Babes combines the basics of a fighting game with realistic real-life video. Players can choose from various (all-female) fighters, with several secret characters incorporated. Play modes include your average ''arcade'' mode, but modes like ''spectacle'' (watch the CPU do all the work), ''practice'' (senselessly beating a passive opponent) and ''marathon'' are also included. As a bonus, the game features some ''Sweet Stuff'', which acts like a jukebox/gallery sort of section, in which themes and movies can be replayed.' FROM games WHERE igdb_id = 51236 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 51236 AND ge.slug = 'fighting' ON CONFLICT DO NOTHING;
