INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystina Online', 'Mystina Online is a massively multiplayer online role-playing game (MMORPG) set in a unique fantasy world where four races—Humans, Beasts, Sylphs, and the Fallen—coexist. In this world, players engage in quests, battles, and treasure hunting, while also collecting heroes to aid them on their journey. One of the game''s core features is its summoning system, allowing players to call upon heroes from different eras, using them as companions in battle.' FROM games WHERE igdb_id = 319462 ON CONFLICT (game_id, language_code) DO NOTHING;
