INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meteorus: O Universo em Conflito', 'Meteorus is an online multiplayer strategy game set in space. The player is the owner of a planet that they must develop technologically through research and construction, mining resources on the surface and in meteors, assembling a fleet of ships to defend themselves against other players, and, above all, getting involved politically with the universe around them.' FROM games WHERE igdb_id = 296190 ON CONFLICT (game_id, language_code) DO NOTHING;
