INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Pinball', 'Ultimate Pinball is a series of 20 different pinball tables which run from separate executables from the launcher. They are grouped by the following categories: Space, Historic, Monster, Sports, and Places. The tables themselves run on the Balls of Steel game engine. Like that game, each of these pinball tables is presented in an overhead view with a "dot pixel" display at the bottom of the screen which relays the player''s score, messages and bonuses. The "goal" of each table varies with the theme but generally the player is expected to shoot & ricochet their pinball into specific places in specific orders. The player''s controls are to move the paddle on the left, move the paddle on the right, launch a new ball and "tilt" (shake) the pinball machine.' FROM games WHERE igdb_id = 206621 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 206621 AND ge.slug = 'pinball' ON CONFLICT DO NOTHING;
