INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('im-gonna-serve-you-4', 139036, '2002-12-06', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8l8m.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I''m Gonna Serve You 4', 'My name is Aoyama Kouji. I''m an ordinary guy living an uneventful life as a university student. Because my parents are separated, my uncle, a somewhat strange man who runs a restaurant, has taken the role of being a father to me. Although it''s hard work, I actually like helping out at the restaurant from time to time. One day, while walking with Himeko, who I''ve been friends with since childhood, I was hit by a car and nearly died! Thanks to a miracle, I awoke to find myself in a hospital bed in America. After some bizarre adventures, I return to Japan and decide to move into my uncle''s house where I can help him run his restaurant. Imagine my surprise when several beautiful girls approach me to tell me how happy they are that we''ll be working together. First, there''s Himeko, who tells me she''ll do anything for me, followed by Chizuru, a beautiful girl who lives in the neighborhood who wants to shower me with attention. Takano, a gorgeous girl from my class, also confesses her desire to do anything she can for me, as does Leo, the quiet girl who lives and works at the restaurant. At first I think they''re just happy that I wasn''t killed in the car accident, but gradually I realize that they''ve all fallen in love with me for some bizarre reason. The girls are spending every moment they can, taking care of me and giving me all their attention. Am I the luckiest guy in the world, or what?' FROM games WHERE igdb_id = 139036 ON CONFLICT (game_id, language_code) DO NOTHING;
