INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('get-backers-dakkanoku-ubawareta-mugenjou', 73632, '2002-09-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob3wz.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Get Backers Dakkanoku: Ubawareta Mugenjou', 'GetBackers Dakkanya: Ubawareta Mugenjou is an action RPG based on the Manga series GetBackers. You control two characters, Ben and Ginji, who possess special powers that allow them to find and to recover items, valuables, and even people who got lost. Now they are offered a huge sum of money for a recovery job they have to do for a mysterious customer from an even more mysterious Castle of Infinity. The gameplay is based on exploration of randomly generated dungeons. You search for items and also trigger important cut scenes by exploring every corner in the dungeons. The action-based combat resembles a fighting game. You can perform a variety of moves, block your opponent''s attack, and switch between the characters. Attacks deplete your stamina bar, so continuously using the strongest attacks is not always the best choice. When your stamina bar is full, you can perform powerful combo attacks.' FROM games WHERE igdb_id = 73632 ON CONFLICT (game_id, language_code) DO NOTHING;
