INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bionicle: Matoran Adventures', 'BIONICLE: Matoran Adventures offers a fun character-switching feature to help players advance through each of the six levels found in the game. Players start as a Matoran and unlock more Matoran characters as they progress. Turaga, with their unique powers, can be "picked up" throughout the game to help the player through an elemental hazard like a lava pool or to activate a switch to a secret door. Once found, that "picked-up" Turaga follows you onwards in your adventure.' FROM games WHERE igdb_id = 6322 ON CONFLICT (game_id, language_code) DO NOTHING;
