INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avernum 3', 'Ten years after Avernum 2, you arrive on the surface from which you were once cast only to find that the Empire has been beset by plagues and hordes of monsters. You must find the source of the destruction or there will be no surface left to return to.' FROM games WHERE igdb_id = 57680 ON CONFLICT (game_id, language_code) DO NOTHING;
