INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beam Breakers', 'With towering skyscrapers and anti-gravity cars changing the metropolis atmosphere, racing has become a more dangerous sport. Death-defying drivers from rival gangs risk everything in wild, illegal races in the middle of rush hour--always on the run from the MetroPolice. Now, a new challenge has come, and you must take control of one of 30 cars and race against five different gangs. Each track takes you through realistic and densely populated living environments.' FROM games WHERE igdb_id = 24082 ON CONFLICT (game_id, language_code) DO NOTHING;
