INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cube', 'Cube is a freeware 3D first-person shooter game. It can be played both in multiplayer and singleplayer mode. It allows the player to edit maps in-engine in full 3D, this means it is possible to fly around the map, point and drag to raise/lower blocks, create slopes etc. Multiple online players can even edit a map simultaneously.' FROM games WHERE igdb_id = 229157 ON CONFLICT (game_id, language_code) DO NOTHING;
