INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Treasure Planet: Etherium Rescue', 'Treasure Planet: Etherium Rescue is one of the three games from the Treasure Planet: Training Academy collection that was distributed by McDonald''s Mighty Kid''s Meals, the other two being Treasure Planet: Treasure Racer and Treasure Planet: Broadside Blast. Etherium Rescue was published by Disney Interactive and released in 2002, along with all the other Treasure Planet related games.' FROM games WHERE igdb_id = 213037 ON CONFLICT (game_id, language_code) DO NOTHING;
