INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue-Sky-Blue(s): Sora o Mau Tsubasa', 'The protagonist''s mom passed away 10 years ago and the father-son relationship is a strained one. When poppy''s work as a weatherman and new marriage sends them to Hokkaido, the player enters a new school and joins up with a group of student''s whose passion is the sky - with the belief that people come from the sky and will eventually return to the sky... Six girls are available for the romancing including honor student Kasumi Itimatsu, school director''s granddaughter Fuuka Mitsuba and assistant teacher Tomomi Shinose.' FROM games WHERE igdb_id = 271420 ON CONFLICT (game_id, language_code) DO NOTHING;
