INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokimeki Memorial Girl''s Side', 'There is a fairy-tale story of a traveling prince who falls in love with a princess but are torn apart. The story is told by a young boy to the main character as a young girl in a church on the grounds of Habataki High School. The boy promises to one day return to that same place to declare his love. The protagonist returns to Habataki High School, after living away for a time due to her parents'' work. While leading a normal high school life including academics, club activities and part-time work, it is also possible to become friendly with boys who can make a declaration of love on graduation day.' FROM games WHERE igdb_id = 72670 ON CONFLICT (game_id, language_code) DO NOTHING;
