INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '911 Paramedic', 'Another interactive game of Legacy Interactive team, known for its medical series Emergency Room. 911: Paramedic combines medical aspects with dramatic decisions to be made by an ambulance nurse. The player plays the role of an inexperienced paramedic who, together with his partner, must save lives until the ambulance arrives.' FROM games WHERE igdb_id = 72049 ON CONFLICT (game_id, language_code) DO NOTHING;
