INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shifters', 'Shifters, also known as Shifters of Might and Magic, is a 2002 action role-playing video game developed and published by The 3DO Company for the PlayStation 2 in 2002. Set in the fictional Might and Magic universe, it is a direct sequel to the PlayStation 2 incarnation of Warriors of Might and Magic.' FROM games WHERE igdb_id = 43557 ON CONFLICT (game_id, language_code) DO NOTHING;
