INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monsters, Inc.: Wreck Room Arcade - Eight Ball Chaos', 'Monsters, Inc. Wreck Room Arcade: Eight Ball Chaos is a part of the Wreck Room Arcade series, designed to offer players a unique blend of entertainment within the Monsters, Inc. universe. Set in the monsters'' after-work hangout, players don''t compete against opponents directly, aiming instead to sink balls into pockets matching their colors, earning points and bonuses for successful shots and tricks.' FROM games WHERE igdb_id = 69576 ON CONFLICT (game_id, language_code) DO NOTHING;
